
.section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.section-head {
  font-size: 12px;
  color: var(--c-accent);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 4px;
}

.section-head i {
  margin-right: 6px;
}

.empty {
  color: var(--c-text-muted);
  font-size: 12px;
}

.item {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 6px 8px;
  background: var(--c-surface-raised);
  border-radius: 4px;
}

.item-name {
  font-weight: bold;
}

.item-desc {
  color: var(--c-text-muted);
  font-size: 12px;
}
