
.section {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.section-head {
  font-size: 12px;
  color: var(--c-accent);
  border-bottom: 1px solid var(--c-border);
  padding-bottom: 4px;
}

.section-head i {
  margin-right: 6px;
}

.empty {
  color: var(--c-text-muted);
  font-size: 12px;
}

.npc-item {
  display: flex;
  flex-direction: column;
  gap: 4px;
  padding: 6px 8px;
  background: var(--c-surface-raised);
  border-radius: 4px;
}

.npc-head {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.item-name {
  font-weight: bold;
}

.favor {
  color: var(--c-primary);
  font-size: 12px;
}

.favor-track {
  height: 6px;
  border-radius: 3px;
  background: var(--c-surface);
  overflow: hidden;
}

.favor-fill {
  height: 100%;
  background: var(--c-primary);
  transition: width 0.25s ease;
}

.item-desc {
  color: var(--c-text-muted);
  font-size: 12px;
}
