
.card {
  width: 100%;
  max-width: 680px;
  margin: 0 auto;
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.4;
  overflow: hidden;
}

.title-bar {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  cursor: pointer;
  background: var(--c-surface-raised);
  border-bottom: 1px solid var(--c-border);
}

.name {
  font-weight: bold;
  color: var(--c-primary);
}

.identity {
  padding: 1px 8px;
  border: 1px solid var(--c-accent);
  border-radius: 10px;
  color: var(--c-accent);
  font-size: 11px;
}

.meta {
  flex: 1;
  color: var(--c-text-muted);
  font-size: 12px;
  text-align: right;
}

.panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 12px 14px;
}
